const input = $input.first().json;

const recordId =
  input.body?.recordId ??
  input.recordId;

if (!recordId) {
  throw new Error(
    `recordId not found. Input: ${JSON.stringify(input)}`
  );
}

return [
  {
    json: {
      recordId,
      method: "GET",
      url: `https://api.airtable.com/v0/appn5d5Ca7g9IyNMf/tblnUG3bEN2QqyKT4/${recordId}`,
      body: null
    }
  }
];

const PROCESSING_STALE_AFTER_MINUTES = 10;

const TERMINAL = new Set([
  'completed',
  'manual_review',
  'privacy_stop',
  'invalid_input',
  'failed'
]);

// Input from Load Lead (retry)
const item = $input.first().json;

// Retry workflow wraps Airtable response into body
const airtableRecord = item?.body ?? item;

const fields = airtableRecord?.fields ?? {};
const recordId = airtableRecord?.id ?? airtableRecord?.recordId ?? '';

// Fail loudly instead of accidentally treating missing data as a new record
if (!recordId) {
  throw new Error(
    `Idempotency Guard: recordId is missing. Input: ${JSON.stringify(item)}`
  );
}

// Original webhook data
const webhook = $('Airtable Trigger').first().json;
const headers = webhook?.headers ?? {};
const webhookBody = webhook?.body ?? {};

// Optional forced rerun
const rerunSecret =
  typeof $vars !== 'undefined'
    ? ($vars.LEAD_INTELLIGENCE_RERUN_SECRET ?? '')
    : '';

const suppliedToken =
  headers['x-lead-rerun-secret'] ??
  webhookBody.control_rerun_token ??
  '';

const forceRerun = !!(
  rerunSecret &&
  suppliedToken &&
  suppliedToken === rerunSecret
);

const enrichmentStatus = fields['Enrichment Status'] ?? '';
const startedAtRaw = fields['Processing Started At'] ?? '';

let proceed = true;
let reason = 'new_record';

if (forceRerun) {
  reason = 'force_rerun';
} else if (TERMINAL.has(enrichmentStatus)) {
  proceed = false;
  reason = 'duplicate_terminal';
} else if (enrichmentStatus === 'processing') {
  let stale = true;

  if (startedAtRaw) {
    const startedAt = new Date(startedAtRaw).getTime();

    if (
      !Number.isNaN(startedAt) &&
      (Date.now() - startedAt) <
        PROCESSING_STALE_AFTER_MINUTES * 60 * 1000
    ) {
      stale = false;
    }
  }

  if (!stale) {
    proceed = false;
    reason = 'duplicate_recent_processing';
  } else {
    reason = 'stale_reentry';
  }
}

return [
  {
    json: {
      recordId,
      fields,
      proceed,
      idempotency_reason: reason,
      run_id: $execution.id,
      processing_started_at: new Date().toISOString(),
      force_rerun: forceRerun
    }
  }
];

const item = $input.first().json;
const recordId = item.recordId;

if (!recordId) {
  throw new Error('recordId is missing');
}

const runId = String(item.run_id ?? $execution.id);
const processingStartedAt =
  item.processing_started_at ?? new Date().toISOString();

return [{
  json: {
    method: "PATCH",
    url: `https://api.airtable.com/v0/appn5d5Ca7g9IyNMf/tblnUG3bEN2QqyKT4/${recordId}`,
    body: {
      fields: {
        "Enrichment Status": "processing",
        "Result Status": "pending",
        "Last Run ID": runId,
        "Processing Started At": processingStartedAt,

        "Input Rejection Reason": null,
        "Manual Review Needed": false,
        "Manual Review Reason": null,
        "Routing Outcome": null,
        "Completed At": null,

        "Domain Status": null,
        "Is Personal Domain": false,
        "Is Role Inbox": false,
        "Name Quality": null,
        "Name Quality Reason": null,

        "Account Resolution Status": null,
        "Account Resolution Reason": null,
        "Account Resolution Evidence": null,
        "Account Company": null,

        "Person Resolution Status": null,
        "Person Resolution Reason": null,
  "Person Resolution Evidence": null,
        "Person": null,

        "Matched Employer Candidate": null,
        "Inbound Employer Verification": null,
        "Matched Employer": null,

        "Organization Relationship": null,
        "Org Relationship Reason": null,
        "Org Relationship Source": null,
        "Org Relationship Evidence": null,

        "HR Discovery Status": null,
        "HR Contacts": null,
        "Flagged HR Contacts": null
      }
    }
  }
}];

const item = $input.first().json;

let record;

if (item && item.body) {
  record = item.body;
} else {
  record = item;
}

let fields = {};

if (record && record.fields) {
  fields = record.fields;
}

let recordId = '';

if (record && record.id) {
  recordId = record.id;
} else if (record && record.recordId) {
  recordId = record.recordId;
}

if (!recordId) {
  throw new Error(
    'Input validation: recordId is missing. Input: ' +
    JSON.stringify(item)
  );
}


// --------------------
// INPUT
// --------------------

const first_name = String(
  fields['Name'] ? fields['Name'] : ''
).trim();

const last_name = String(
  fields['Last Name'] ? fields['Last Name'] : ''
).trim();

const email = String(
  fields['Email'] ? fields['Email'] : ''
).trim();

const run_id = fields['Last Run ID']
  ? fields['Last Run ID']
  : String($execution.id);

const processing_started_at = fields['Processing Started At']
  ? fields['Processing Started At']
  : '';


// --------------------
// FREE / PERSONAL EMAIL DOMAINS
// --------------------

const FREE_EMAIL = new Set([
  'gmail.com',
  'googlemail.com',
  'outlook.com',
  'hotmail.com',
  'live.com',
  'msn.com',
  'yahoo.com',
  'ymail.com',
  'icloud.com',
  'me.com',
  'mac.com',
  'proton.me',
  'protonmail.com',
  'mail.ru',
  'inbox.ru',
  'list.ru',
  'bk.ru',
  'rambler.ru',
  'aol.com',
  'gmx.com',
  'gmx.net',
  'zoho.com'
]);


// --------------------
// ROLE / SHARED INBOXES
// --------------------

const ROLE_PREFIX = new Set([
  'hr',
  'jobs',
  'careers',
  'career',
  'recruitment',
  'recruiting',
  'talent',
  'people',
  'info',
  'hello',
  'contact',
  'support',
  'sales',
  'marketing',
  'office',
  'admin',
  'team',
  'operations',
  'ops',
  'hiring',
  'work',
  'jobseu',
  'careerseu'
]);


// --------------------
// NAME PLACEHOLDERS
// --------------------

const PLACEHOLDER = new Set([
  'test',
  'asdf',
  'qwerty',
  'foo',
  'bar',
  'na',
  'n/a',
  'unknown',
  'user',
  'name',
  'firstname',
  'lastname',
  'xxx',
  'none'
]);


// --------------------
// EMAIL PARSING
// --------------------

let domain_status = 'INVALID_FORMAT';
let is_personal_domain = false;
let email_domain = '';
let email_local = '';

const em = email.match(/^([^@\s]+)@([^@\s]+\.[^@\s]+)$/);

if (em) {
  email_local = em[1].toLowerCase();
  email_domain = em[2].toLowerCase();

  if (FREE_EMAIL.has(email_domain)) {
    domain_status = 'FREE_EMAIL';
    is_personal_domain = true;
  } else {
    domain_status = 'BUSINESS';
  }
}


// --------------------
// SYSTEM / NO-REPLY INBOX
// --------------------

const normLocal = email_local
  .toLowerCase()
  .replace(/[^a-z0-9]/g, '');

const SYSTEM_MAILBOX_PATTERN =
  /noreply|donotreply|noresponse|jobalerts|jobalert|careeralerts|careeralert|notifications|notification|mailerdaemon|postmaster|bounce/i;

const is_system_inbox =
  SYSTEM_MAILBOX_PATTERN.test(normLocal);


// --------------------
// ROLE / SHARED INBOX
// --------------------

const emailTokens = email_local
  .toLowerCase()
  .split(/[._+\-]+/)
  .filter(function(token) {
    return token.length > 0;
  });

let roleTokenFound = false;

for (let i = 0; i < emailTokens.length; i++) {
  if (ROLE_PREFIX.has(emailTokens[i])) {
    roleTokenFound = true;
    break;
  }
}

let is_role_inbox = false;

if (!is_system_inbox) {
  if (ROLE_PREFIX.has(normLocal) || roleTokenFound) {
    is_role_inbox = true;
  }
}


// --------------------
// NAME QUALITY
// --------------------

const letters = (first_name + last_name)
  .replace(/[^A-Za-z]/g, '');

const combined =
  (first_name + ' ' + last_name).trim();

const supplied_name =
  combined ? combined : null;

let name_quality = 'VALID';
let name_quality_reason = null;

if (!letters || letters.length < 2) {

  name_quality = 'INVALID';
  name_quality_reason =
    'No usable alphabetic name characters.';

} else if (
  PLACEHOLDER.has(first_name.toLowerCase()) ||
  PLACEHOLDER.has(last_name.toLowerCase()) ||
  PLACEHOLDER.has(combined.toLowerCase()) ||
  /(.)\1{4,}/.test(letters)
) {name_quality = 'INVALID';
  name_quality_reason =
    'Placeholder or gibberish name.';

} else if (letters.length <= 2) {

  name_quality = 'SUSPICIOUS';
  name_quality_reason =
    'Very short name; plausible but uncertain.';
}


// --------------------
// OUTPUT
// --------------------

return [
  {
    json: {
      recordId: recordId,

      input: {
        first_name: first_name,
        last_name: last_name
      },

      email: email,
      email_domain: email_domain,
      email_local: email_local,

      domain_status: domain_status,
      is_personal_domain: is_personal_domain,
      is_role_inbox: is_role_inbox,
      is_system_inbox: is_system_inbox,

      name_quality: name_quality,
      name_quality_reason: name_quality_reason,
      supplied_name: supplied_name,

      run_id: run_id,
      processing_started_at: processing_started_at
    }
  }
];

const item = $input.first().json;

let recordId = '';

if (item.recordId) {
  recordId = String(item.recordId).trim();
} else if (item.airtable_record_id) {
  recordId = String(item.airtable_record_id).trim();
} else if (item.body && item.body.id) {
  recordId = String(item.body.id).trim();
} else if (
  item.body &&
  item.body.fields &&
  item.body.fields['Record ID']
) {
  recordId = String(item.body.fields['Record ID']).trim();
}

if (!recordId) {
  throw new Error(
    'Pack Privacy: recordId is missing. Input: ' +
    JSON.stringify(item)
  );
}

const url =
  'https://api.airtable.com/v0/appn5d5Ca7g9IyNMf/tblnUG3bEN2QqyKT4/' +
  recordId;

return [
  {
    json: {
      method: 'PATCH',
      url: url,
      body: {
        fields: {
          'Enrichment Status': 'privacy_stop',
          'Result Status': 'invalid',
          'Routing Outcome': 'PRIVACY_STOP',
          'Input Rejection Reason': 'personal_email',
          'Person Resolution Status': 'SKIPPED_PRIVACY',
          'Person Resolution Reason':
            'Free or personal email address; identity resolution skipped.'
        }
      }
    }
  }
];

const item = $input.first().json;

let recordId = '';

if (item.recordId) {
  recordId = String(item.recordId).trim();
} else if (item.airtable_record_id) {
  recordId = String(item.airtable_record_id).trim();
} else if (item.body && item.body.id) {
  recordId = String(item.body.id).trim();
} else if (
  item.body &&
  item.body.fields &&
  item.body.fields['Record ID']
) {
  recordId = String(item.body.fields['Record ID']).trim();
}

if (!recordId) {
  throw new Error(
    'Pack Invalid: recordId is missing. Input: ' +
    JSON.stringify(item)
  );
}


// --------------------
// READ GUARDRAILS
// --------------------

let isSystemInbox = false;
let domainStatus = '';
let nameQuality = '';

if (item.is_system_inbox === true) {
  isSystemInbox = true;
} else if (
  item.body &&
  item.body.fields &&
  item.body.fields['Is System Inbox'] === true
) {
  isSystemInbox = true;
}

if (item.domain_status) {
  domainStatus = String(item.domain_status);
} else if (
  item.body &&
  item.body.fields &&
  item.body.fields['Domain Status']
) {
  domainStatus = String(
    item.body.fields['Domain Status']
  );
}

if (item.name_quality) {
  nameQuality = String(item.name_quality);
} else if (
  item.body &&
  item.body.fields &&
  item.body.fields['Name Quality']
) {
  nameQuality = String(
    item.body.fields['Name Quality']
  );
}


// --------------------
// REJECTION REASON
// --------------------

let rejectionReason = 'invalid_input';

if (isSystemInbox === true) {
  rejectionReason = 'system_inbox';
} else if (domainStatus === 'INVALID_FORMAT') {
  rejectionReason = 'invalid_email';
} else if (nameQuality === 'INVALID') {
  rejectionReason = 'invalid_name';
}


// --------------------
// AIRTABLE PATCH
// --------------------

const url =
  'https://api.airtable.com/v0/appn5d5Ca7g9IyNMf/tblnUG3bEN2QqyKT4/' +
  recordId;

return [
  {
    json: {
      method: 'PATCH',
      url: url,
      body: {
        fields: {
          'Enrichment Status': 'invalid_input',
          'Result Status': 'invalid',
          'Routing Outcome': 'INVALID_INPUT',
          'Input Rejection Reason': rejectionReason
        }
      }
    }
  }
];

const n = $('Normalize Validate').first().json;

return [{
  json: {
    normalized: n
  }
}];

const d = $input.first().json;
const n = $('Normalize Validate').first().json;

const status = String(
  d.domain_verification_status
    ? d.domain_verification_status
    : ''
);

const reason = d.domain_verification_reason
  ? String(d.domain_verification_reason)
  : null;

let terminal = null;

if (status === 'INVALID_DOMAIN') {
  terminal = 'invalid_domain';
}

if (status === 'TECHNICAL_ERROR') {
  terminal = 'technical_dns';
}

return [{
  json: {
    ...n,
    domain_verification_status: status,
    domain_verification_reason: reason,
    _terminal: terminal
  }
}];

const item = $input.first().json;

let recordId = '';

if (item.recordId) {
  recordId = String(item.recordId).trim();
} else if (item.airtable_record_id) {
  recordId = String(item.airtable_record_id).trim();
}

if (!recordId) {
