return [
  {
    json: {
      method: 'PATCH',
      url: url,
      body: {
        fields: {
          'Enrichment Status': 'failed',
          'Result Status': 'failed',
          'Routing Outcome': 'FAILED'
        }
      }
    }
  }
];
